import React, { useState } from "react";
import { TextField, Button, Select, MenuItem, TextareaAutosize } from "@mui/material";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";

const VendorsPage: React.FC = () => {
  const [vendorData, setVendorData] = useState({
    vendorName: "",
    vendorType: "",
    description: "",
    pricing: "",
    instagramLink: "",
    website: "",
    phone: "",
    email: "",
    availableDates: [] as string[], // Added available dates array
  });

  const [editingVendorId, setEditingVendorId] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setVendorData({ ...vendorData, [e.target.name]: e.target.value });
  };

  const handleDateChange = (date: any) => {
    setVendorData((prevData) => ({
      ...prevData,
      availableDates: [...prevData.availableDates, date.toISOString()],
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const url = editingVendorId
        ? `http://localhost:5000/vendors/${editingVendorId}` // PUT request when editing
        : "http://localhost:5000/vendors"; // POST request when adding new vendor

      const method = editingVendorId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(vendorData),
      });

      if (response.ok) {
        setSuccessMessage(editingVendorId ? "Vendor updated successfully!" : "Vendor added successfully!");
        setVendorData({
          vendorName: "",
          vendorType: "",
          description: "",
          pricing: "",
          instagramLink: "",
          website: "",
          phone: "",
          email: "",
          availableDates: [],
        });
        setEditingVendorId(null); // Reset editing mode
      } else {
        const errorData = await response.json();
        setError(errorData.message || "Operation failed.");
      }
    } catch (error) {
      console.error("Error:", error);
      setError("An error occurred.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>{editingVendorId ? "Update Vendor" : "Vendor Registration"}</h2>
      {error && <p style={{ color: "red" }}>{error}</p>}
      {successMessage && <p style={{ color: "green" }}>{successMessage}</p>}
      <form onSubmit={handleSubmit}>
        <TextField
          type="text"
          name="vendorName"
          label="Vendor Name"
          placeholder="Vendor Name"
          value={vendorData.vendorName}
          onChange={handleChange}
          required
        />
        <Select
          name="vendorType"
          value={vendorData.vendorType}
          onChange={handleChange}
          required
        >
          <MenuItem value="">Select Vendor Type</MenuItem>
          <MenuItem value="Venue">Venue</MenuItem>
          <MenuItem value="Caterer">Caterer</MenuItem>
          <MenuItem value="Hair">Hair</MenuItem>
          <MenuItem value="Makeup">Makeup</MenuItem>
          <MenuItem value="Photography">Photography</MenuItem>
          <MenuItem value="Music">Music</MenuItem>
          <MenuItem value="Florist">Florist</MenuItem>
          <MenuItem value="Dresser">Dresser</MenuItem>
          <MenuItem value="Planner">Planner</MenuItem>
        </Select>
        <TextareaAutosize
          name="description"
          placeholder="Description"
          value={vendorData.description}
          onChange={handleChange}
        />
        <TextField
          type="text"
          name="pricing"
          label="Pricing"
          placeholder="Pricing"
          value={vendorData.pricing}
          onChange={handleChange}
        />
        <TextField
          type="text"
          name="instagramLink"
          label="Instagram Link"
          placeholder="Instagram Link"
          value={vendorData.instagramLink}
          onChange={handleChange}
        />
        <TextField
          type="text"
          name="website"
          label="Website"
          placeholder="Website"
          value={vendorData.website}
          onChange={handleChange}
        />
        <TextField
          type="text"
          name="phone"
          label="Phone"
          placeholder="Phone"
          value={vendorData.phone}
          onChange={handleChange}
        />
        <TextField
          type="email"
          name="email"
          label="Email"
          placeholder="Email"
          value={vendorData.email}
          onChange={handleChange}
          required
        />

        {/* Calendar Picker for Availability */}
        <LocalizationProvider dateAdapter={AdapterDateFns}>
          <DatePicker
            label="Select Available Date"
            value={null} // This will be handled dynamically
            onChange={handleDateChange}
            renderInput={(params) => <TextField {...params} />} // Pass params to the TextField directly
          />
        </LocalizationProvider>

        <Button type="submit" disabled={loading}>
          {loading ? "Submitting..." : editingVendorId ? "Update Vendor" : "Submit"}
        </Button>
      </form>
    </div>
  );
};

export default VendorsPage;


